import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import type { APIRequestContext } from "@playwright/test";
import { activityRosterUrl } from "../../src/lib/activityRoster";

/** Read only the mailbox generated by the isolated test SMTP transport. */
export function fixtureMfaCode(email: string) {
  const { directory } = JSON.parse(fs.readFileSync(".data/browser-fixture-path.json", "utf8"));
  if (!directory.startsWith(path.join(os.tmpdir(), "scharade-browser-")) || !email.endsWith("@example.invalid")) throw new Error("Invalid synthetic mailbox");
  const mail = JSON.parse(fs.readFileSync(path.join(directory, "synthetic-mail.json"), "utf8"))[email.toLowerCase()];
  const code = mail?.match(/確認コード：(\d{6})/)?.[1];
  if (!code) throw new Error("Synthetic confirmation email missing");
  return code as string;
}

/** Finish the real mandatory email MFA gate for synthetic browser fixtures. */
export async function fixtureLogin(request: APIRequestContext, url: string, options: any = {}) {
  const headers = { ...options.headers, "X-Real-IP": `192.0.2.${crypto.randomInt(1, 255)}` };
  const response = await request.post(url, { ...options, headers });
  if (!response.ok()) return response;
  const body = await response.json(); if (!body.mfaRequired) return response;
  const { directory } = JSON.parse(fs.readFileSync(".data/browser-fixture-path.json", "utf8"));
  if (!directory.startsWith(path.join(os.tmpdir(), "scharade-browser-"))) throw new Error("Invalid synthetic fixture directory");
  const email = String(options.data?.email ?? "").toLowerCase();
  const mail = JSON.parse(fs.readFileSync(path.join(directory, "synthetic-mail.json"), "utf8"))[email];
  const code = mail?.match(/確認コード：(\d{6})/)?.[1];
  if (!code) throw new Error("Synthetic confirmation email missing");
  const rawCookie = response.headers()["set-cookie"] ?? "";
  const challengeCookie = rawCookie.match(/(?:^|,\s*)(__Host-mfa|mfa)=([^;]+)/);
  const mfaHeaders = { ...headers, ...(challengeCookie ? { Cookie: `${challengeCookie[1]}=${challengeCookie[2]}` } : {}) };
  return request.post("/api/auth/mfa", { headers: mfaHeaders, data: { action: "verify", code } });
}

/** Restore the synthetic roster through the same reviewed administrator API. */
export async function restoreFixtureRoster(request: APIRequestContext) {
  const page = await request.get("/Admin/grouping-roster");
  if (!page.ok()) throw new Error("Synthetic administrator session required");
  const revision = Number((await page.text()).match(/data-activity-action="roster.sync" data-revision="(\d+)"/)?.[1] ?? 0);
  const headers = { Origin: "http://127.0.0.1:4329" };
  const preview = await request.post("/api/member/activities", { headers, data: { action: "roster.preview", url: activityRosterUrl, revision } });
  if (!preview.ok()) throw new Error(`Synthetic roster preview failed: ${preview.status()}`);
  const { previewId } = await preview.json();
  const applied = await request.post("/api/member/activities", { headers, data: { action: "roster.apply", previewId, confirm: true } });
  if (!applied.ok()) throw new Error(`Synthetic roster restore failed: ${applied.status()}`);
}
